import React from 'react';
import { useTier } from '../config/TierContext';

export default function Settings() {
  const { tier } = useTier();

  return (
    <div style={{ minHeight: '100vh', backgroundColor: '#F5F4FA' }}>
      <div style={{ padding: '2rem 2.5rem' }}>
        <h1 style={{ fontSize: 28, fontWeight: 700, color: '#130829', margin: 0 }}>Settings</h1>
        <p style={{ fontSize: 14, color: '#6B7280', margin: '4px 0 0' }}>
          Manage your account and portal preferences
        </p>
      </div>
      <div style={{ padding: '0 2.5rem' }}>
        <div
          style={{
            backgroundColor: '#fff',
            borderRadius: 12,
            padding: '1.5rem 2rem',
            border: '1px solid #E5E7EB',
          }}
        >
          <h2 style={{ fontSize: 16, fontWeight: 600, color: '#130829', margin: '0 0 16px' }}>Account</h2>
          <div style={{ display: 'flex', flexDirection: 'column', gap: 16 }}>
            {[
              { label: 'Organisation', value: 'JETT Analytics' },
              { label: 'Subscription', value: `${tier} Tier` },
              { label: 'Region', value: 'Global' },
              { label: 'Platform', value: 'Travel-as-a-Service' },
            ].map((item) => (
              <div key={item.label} style={{ display: 'flex', justifyContent: 'space-between', borderBottom: '1px solid #F3F4F6', paddingBottom: 12 }}>
                <span style={{ fontSize: 14, color: '#6B7280' }}>{item.label}</span>
                <span style={{ fontSize: 14, fontWeight: 600, color: '#130829' }}>{item.value}</span>
              </div>
            ))}
          </div>
        </div>
      </div>
    </div>
  );
}
